package com.bank.rates;

import java.math.BigDecimal;
import java.util.logging.*;

public class FinalAssignDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        final int a = 20;          // final primitive, compile-time constant
        int b = a;                 // ALLOWED: read a, copy value into b
        final int c = a;           // ALLOWED: c assigned once, from a's value
        b = b + 5;                 // ALLOWED: b is NOT final, change it freely
        // a = 30;                 // COMPILE ERROR: cannot reassign final a

        log.info(() -> "a (final) = " + a);
        log.info(() -> "b (copied then +5) = " + b);
        log.info(() -> "c (final copy of a) = " + c);

        InterestEngine engine = new InterestEngine();
        engine.classifyTier(a);
        BigDecimal interest = engine.monthlyInterest(new BigDecimal("1000000.00"), a);
        log.info(() -> "Interest for SAV2001 (Rajesh) = Rs." + interest);
    }
}

