class InterestEngine {
    private static final Logger log = Logger.getLogger("BankLog");

    // A final primitive constant can be used as a switch label (constant folding).
    void classifyTier(final int ratePercent) {
        int working = ratePercent; // copy final value into a mutable local
        switch (working) {
            case 20 -> log.info("Rate 20% classified as PROMO tier");
            default -> log.info("Standard tier");
        }
    }

    java.math.BigDecimal monthlyInterest(BigDecimal principal, int ratePercent) {
        return principal.multiply(BigDecimal.valueOf(ratePercent))
                        .divide(new BigDecimal("100"), 2, java.math.RoundingMode.HALF_EVEN)
                        .divide(new BigDecimal("12"), 2, java.math.RoundingMode.HALF_EVEN);
    }
}
